service.method:

		WITH UPSERT AS (
			 SELECT ''
		   ),
	  UPDATE_OPTION AS (
	  		 UPDATE SUSMT
	  		    SET COMPANY_CODE   = ${COMPANY_CODE}
		          , PLANT_CODE     = ${PLANT_CODE}
		          , CHANGE_DATE    = ${current.DATE}
		          , CHANGE_TIME    = ${current.TIME}
		          , DEPT           = ${DEPT}
		          , USER_NAME_LOC  = ${USER_NAME_LOC}
		          , USER_NAME_ENG  = ${USER_NAME_ENG}
		          , LANGUAGE       = ${LANGUAGE}
		          , TIME_ZONE      = ${TIME_ZONE}
		          , EMAIL          = ${EMAIL}
		          , COUNTRY        = ${COUNTRY}
		          , STATE          = ${STATE}
		          , EMPLOYEE_NO    = ${EMPLOYEE_NO}
		          , SIGN_STATUS    = 'A'
		          , POSITION       = ${POSITION}
		          , WORK_TYPE      = ${WORK_TYPE}
		          , USER_TYPE      = ${USER_TYPE}
		          , THEME          = ${THEME}
		          , CHANGE_USER_ID = ${session.ID}
		          , DATE_FORMAT    = ${DATE_FORMAT}
		          , PHONE_NO1      = ${PHONE_NO1}
		          , PHONE_NO2      = ${PHONE_NO2}
		          , FAX_NO         = ${FAX_NO}
		          , ZIP_CODE       = ${ZIP_CODE}    
           		  , ADDRESS_LOC    = ${ADDRESS_LOC}
           		  , ADDRESS_ENG    = ${ADDRESS_ENG}
           		  , MENU_PROFILE_CODE = ${MENU_PROFILE_CODE}


		          , PASSWORD       = ${PASSWORD_1}
		          , PW_RESET_FLAG  = 'Y'
		          , PW_RESET_DATE  = ${current.DATE}  


		      WHERE USER_ID    = ${USER_ID} 
                AND HOUSE_CODE = ${session.HOUSE_CODE}
	       )
			 INSERT INTO 
			  SUSMT (
			   	    HOUSE_CODE
				  , USER_ID
				  , ADD_DATE
				  , ADD_TIME
				  , ADD_USER_ID
				  , CHANGE_DATE
				  , CHANGE_TIME
				  , CHANGE_USER_ID
				  , COMPANY_CODE
				  , PLANT_CODE
				  , USER_NAME_LOC
				  , USER_NAME_ENG
				  , DEPT
				  , POSITION
				  , LANGUAGE
				  , MENU_TYPE
				  , TIME_ZONE
				  , EMAIL
				  , COUNTRY
				  , STATE
				  , EMPLOYEE_NO
				  , SIGN_STATUS
				  , WORK_TYPE
				  , MENU_PROFILE_CODE
				  , USER_TYPE
				  , PASS_CHECK_CNT
				  , DEL_FLAG
				  , LAST_LOGIN_DATE
				  , LAST_LOGIN_TIME
				  , LAST_LOGIN_IP
				  , THEME
				  , DATE_FORMAT
				  , CTRL_CODE
				  , PHONE_NO1   
                  , PHONE_NO2   
                  , FAX_NO      
                  , ZIP_CODE    
                  , ADDRESS_LOC 
                  , ADDRESS_ENG 


	              , PASSWORD
	              , PW_RESET_FLAG
	              , PW_RESET_DATE


	              ) 
	         SELECT ${session.HOUSE_CODE}
	              , ${USER_ID}
	              , ${current.DATE}
	              , ${current.TIME}
	              , ${USER_ID}
	              , ${current.DATE}
	              , ${current.TIME}
	              , ${USER_ID}
	              , ${COMPANY_CODE}
	              , ${PLANT_CODE}
	              , ${USER_NAME_LOC}
	              , ${USER_NAME_ENG}
	              , ${DEPT}
	              , ${POSITION}
	              , ${LANGUAGE}
	              , ${MENU_TYPE}
	              , ${TIME_ZONE}
	              , ''
	              , ${COUNTRY}
	              , ${STATE}
	              , ${EMPLOYEE_NO}
	              , 'A'
	              , 'Z'
	              , ${MENU_PROFILE_CODE}
	              , ${USER_TYPE}
	              , '0'
	              , 'N'
	              , ${current.DATE}
	              , ${current.TIME}
	              , ${LAST_LOGIN_IP}
	              , ${THEME}
	              , ${DATE_FORMAT}
	              , ${CTRL_CODE}
	              , ${PHONE_NO1}  
                  , ${PHONE_NO2}  
                  , ${FAX_NO}     
                  , ${ZIP_CODE}   
                  , ${ADDRESS_LOC}
                  , ${ADDRESS_ENG}


		          , ${PASSWORD_1}
		          , 'Y'
		          , ${current.DATE}


	          WHERE NOT EXISTS (
	                SELECT USER_ID
	          		  FROM SUSMT
	          		 WHERE USER_ID    = ${USER_ID} 
                       AND HOUSE_CODE = ${session.HOUSE_CODE}
	       )


    	UPDATE SUSMT
      	   SET PHONE_NO1      = ${PHONE_NO1}  
             , PHONE_NO2      = ${PHONE_NO2}  
             , FAX_NO         = ${FAX_NO}     
             , ZIP_CODE       = ${ZIP_CODE}   
             , ADDRESS_LOC    = ${ADDRESS_LOC}
             , ADDRESS_ENG    = ${ADDRESS_ENG}
      	     , CHANGE_DATE    = ${current.DATE}
	         , CHANGE_TIME    = ${current.TIME}
	         , CHANGE_USER_ID = ${session.ID}
	         , USER_NAME_LOC  = ${USER_NAME_LOC}
	         , USER_NAME_ENG  = ${USER_NAME_ENG}


		  ,PASSWORD = ${PASSWORD_1}
		  ,PW_RESET_FLAG = 'Y'
		  ,PW_RESET_DATE = ${current.DATE}  


      WHERE USER_ID  = ${session.ID}
        AND HOUSE_CODE = ${session.HOUSE_CODE}


		WITH UPSERT AS (
			 SELECT ''
		   ),
 	  UPDATE_OPTION AS (
	  		 UPDATE SADDR
	  		    SET CHANGE_DATE    = ${current.DATE},
		            CHANGE_TIME    = ${current.TIME},
		            CHANGE_USER_ID = ${session.ID},
		            EMAIL          = ${EMAIL},
		            PHONE_NO1      = ${PHONE_NO1},
		            PHONE_NO2      = ${PHONE_NO2},
		            FAX_NO         = ${FAX_NO}
	          WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	            AND CODE_NO    = ${USER_ID}
	            AND CODE_TYPE  = 'USER'
	            )
	     INSERT iNTO SADDR(
     	              HOUSE_CODE
					, CODE_NO
					, CODE_TYPE
					, ZIP_CODE
					, PHONE_NO1
					, FAX_NO
					, HOMEPAGE
					, ADDRESS_LOC
					, ADDRESS_ENG
					, CEO_NAME_LOC
					, CEO_NAME_ENG
					, EMAIL
					, ZIP_BOX_NO
					, PHONE_NO2
					, ADD_DATE
					, ADD_TIME
					, ADD_USER_ID
					, CHANGE_DATE
					, CHANGE_TIME
					, CHANGE_USER_ID
					, DEL_FLAG
					, ADDRESS_TEXT
			) SELECT
					  ${session.HOUSE_CODE}
					, ${USER_ID}
					, 'USER'
					, ${ZIP_CODE}
					, ${PHONE_NO1}
					, ${FAX_NO}
					, ${HOMEPAGE}
					, ${ADDRESS_LOC}
					, ${ADDRESS_ENG}
					, ${CEO_NAME_LOC}
					, ${CEO_NAME_ENG}
					, ${EMAIL}
					, ${ZIP_BOX_NO}
					, ${PHONE_NO2}
					, ${current.DATE}
				    , ${current.TIME}
				    , ${USER_ID}
				    , ${current.DATE}
				    , ${current.TIME}
				    , ${USER_ID}
				    , 'N'
				    , ${ADDRESS_TEXT}
			    WHERE NOT EXISTS (
                 SELECT EMAIL
	               FROM SADDR
	              WHERE HOUSE_CODE = ${session.HOUSE_CODE}
		            AND CODE_NO    = ${USER_ID}
		            AND CODE_TYPE  = 'USER'			    
				)
